// ❌ OLD: A scroll listener updates a style on every scroll event.
// Each update touches the main thread (event -> JS -> style recalc),
// and un-throttled listeners can fire many times per frame, causing
// jank and missed frames on low-end devices.
const bar = document.querySelector('.progress-bar');

addEventListener('scroll', () => {
  const max = document.documentElement.scrollHeight - innerHeight;
  const p = scrollY / max; // ❌ OLD: main-thread sample per event
  bar.style.transform = `scaleX(${p})`; // ❌ OLD: style write -> recalc
});

// Also needs passive:true, rAF throttling, resize handling, and
// cleanup — a surprising amount of JS for one progress bar.

/* ✅ NEW: The animation's time source is the scroll position itself,
   sampled on the compositor thread. No listeners, no rAF, no style
   writes from JS — the progress bar tracks the scroll perfectly. */

.progress-bar {
  transform-origin: left;
  animation: grow linear; /* ✅ NEW: 'linear' eases the timeline mapping */
  animation-timeline: scroll(); /* ✅ NEW: scroll position drives progress */
  animation-range: cover 0% cover 100%; /* ✅ NEW: whole scrollable range */
}

@keyframes grow {
  from { transform: scaleX(0); }
  to { transform: scaleX(1); }
}

/* For element-relative effects, use view() and animation-range:
   .reveal { animation-timeline: view();
             animation-range: entry 0% cover 40%; } */
